{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _initFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _loading = false;

  String _searchQuery = '';
  bool _animationStarted = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _initFuture = _loadPage(0, append: false);
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadPage(int page, {required bool append}) async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() => _loading = true);

    try {
      final CurrencyPage result = await currencyRepository.fetchRates(CurrencyPageRequest(page: page));
      if (append) {
        _allCurrencies = List<CurrencyModel>.from(_allCurrencies)..addAll(result.items);
      } else {
        _allCurrencies = result.items;
      }

      _currentPage = page + 1;
      _hasMore = result.hasMore;

      if (!append) {
        currencyRepository.saveCurrencyList(_allCurrencies);
      }

      // Пересчитываем фильтр с текущим поисковым запросом
      _applyFilter();

      setState(() {}); // обновить UI после загрузки
    } finally {
      setState(() => _loading = false);
    }
  }

  void _applyFilter() {
    final String lowerQuery = _searchQuery.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;
    _applyFilter();
  }

  Future<void> _loadMore() async {
    if (_loading || !_hasMore) return;
    await _loadPage(_currentPage, append: true);
  }

  void _startAnimationOnce() {
    if (_animationStarted) return;
    _animationStarted = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && !_fadeController.isAnimating) {
        _fadeController.forward();
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (!snapshot.hasData && !_loading && _allCurrencies.isEmpty) {
            return const Center(child: CircularProgressIndicator());
          }

          // Запускаем анимацию один раз при первом успешном билде
          _startAnimationOnce();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length && _hasMore) {
                            return Center(
                              child: Padding(
                                padding: const EdgeInsets.all(24.0),
                                child: ElevatedButton.icon(
                                  onPressed: _loading ? null : _loadMore,
                                  icon: _loading
                                      ? SizedBox(
                                          width: 18,
                                          height: 18,
                                          child: CircularProgressIndicator(strokeWidth: 2),
                                        )
                                      : Icon(Icons.add_circle_outline),
                                  label: Text(context.loc.showMore),
                                ),
                              ),
                            );
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
